animIndex = 0
stunTime = 0
anim = 'idle' # idle, flowerPunch1, flowerPunch2, carCharge, carChargeBlock, carPunch, carPunchBlock
charging = False
blocking = is_pressed('right')

animSpeed = 1

carHP = 100
carTime = 12
carMode = 'idle'
carSpeed = 1
phase = 1

curtain = 0

def render():
    global animIndex, blocking, spr_fights, curtain
    width, height = d.width, d.height
    startX = int((width - 64)/2)
    startY = int((height - 48)/2)

    # FIGHTERS LAYER
    curMatrix = []
    if anim == 'idle':
        if animIndex >= 4: animIndex = 0
        curMatrix = spr_fights[0:4][int(animIndex)]
    elif anim == 'flowerPunch1':
        if animIndex >= 4: animIndex = 3
        curMatrix = spr_fights[4:8][int(animIndex)]
    elif anim == 'flowerPunch2':
        if animIndex >= 4: animIndex = 3
        curMatrix = spr_fights[10:14][int(animIndex)]
    elif anim == 'carCharge':
        if animIndex >= 2: animIndex = 0

        if blocking: curMatrix = spr_fights[14:16][int(animIndex)]
        else: curMatrix = spr_fights[16:18][int(animIndex)]
    elif anim == 'carPunch':
        if animIndex >= 4: animIndex = 3
        curMatrix = spr_fights[18:22][int(animIndex)]
    elif anim == 'carPunchBlock':
        if animIndex >= 4: animIndex = 3
        curMatrix = spr_fights[22:26][int(animIndex)]

    layer = m.merge_matrixes([-1]*width*height, width, height, curMatrix, startX, startY, 64, 48)
    
    # GUI
    hpMatrix = []
    for i in range(d.width):
        if (i+1)/d.width <= carHP/100: hpMatrix.append(1)
        else: hpMatrix.append(0)
    
    y = 5
    guiLayer = [-1]*width*(height-y-1) + [0]*width + hpMatrix + [0]*width + [-1]*width*(y-1)
    curtainMatrix = [1]*curtain + [-1]*(width*height - curtain)
    guiLayer = m.merge_matrixes(guiLayer, width, height, curtainMatrix, 0, 0, width, height)

    d.update_layer('fighters', layer)
    d.update_layer('gui', guiLayer)

def setAnim(_anim):
    global animIndex
    animIndex = 0
    anim = _anim


punchMode = True
def update():
    global animIndex, anim, animSpeed, stunTime, carMode, carTime, carSpeed, carHP, charging, blocking, punchMode, phase, curtain
    width, height = d.width, d.height

    blocking = is_pressed('right')

    animIndex += animSpeed
    if stunTime > 0: stunTime -= 1

    if carHP <= 0 and phase == 1:
        phase = 2
    
    if phase == 2:
        if carHP < 100:
            carHP += 5
        if carHP >= 100:
            carHP = 100
            phase = 3
            carSpeed = 2
    
    if phase == 3:
        if carHP <= 0:
            phase = 4
    
    if phase == 4:
        carHP = 0
        if curtain < d.width*d.height:
            curtain += int(d.width*1.6)
            if curtain >= d.width*d.height:
                quitGame()
                curtain = d.width*d.height


    # CAR LOGIC
    if carMode == 'idle':
        if anim == 'idle':
            animSpeed = 1
        else:
            animSpeed = 2
        if carTime == 0:
            carTime = 20
            carMode = 'charging'
    
    if carMode == 'charging':
        animSpeed = 1
        anim = 'carCharge'
        charging = True
        if carTime == 0:
            carTime = 15
            carMode = 'punch'
    
    if carMode == 'punch':
        print()
        charging = False
        animSpeed = 2

        if blocking:
            if anim != 'carPunchBlock':
                stunTime = 15
                anim = 'carPunchBlock'
                animIndex = 0
        else:
            if anim != 'carPunch':
                stunTime = 15
                anim = 'carPunch'
                animIndex = 0
                carHP += 10
                if carHP > 100: carHP = 100
        
        if carTime == 0:
            carTime = random.randint(7, 35)
            carMode = 'idle'
    

    if carTime > 0:
        carTime -= carSpeed
        if carTime < 0: carTime = 0

    # PLAYER LOGIC
    if is_pressed('left') and stunTime == 0 and carMode == 'idle':

        if anim not in ['flowerPunch1', 'flowerPunch2']:
            if punchMode:
                anim = 'flowerPunch1'
            else:
                anim = 'flowerPunch2'
            punchMode = not punchMode
            stunTime = 3
            animIndex = 0
            
            dmg = random.randint(3, 9)
            carHP -= dmg
    elif stunTime == 0 and carMode == 'idle':
        anim = 'idle'




    render()

def frameLoop():
    t1 = time.time()
    
    update()
    d.push_frame()
    
    t2 = time.time()

    if t2 - t1 < 1/framerate:
        time.sleep(1/framerate - (t2 - t1))

runGame = True

def quitGame():
    #d.reset()
    global runGame
    runGame = False

while runGame:
    frameLoop()